'use client';

import { useId, useState, type CSSProperties } from 'react';
import './product-spotlight-hero.css';

export interface ProductSpotlightImage {
  src: string;
  alt: string;
}

export interface ProductSpotlightFeature {
  id: string;
  label: string;
  detail: string;
  /** Positions from 0 to 1, relative to the complete main image. */
  x: number;
  y: number;
}

export interface ProductSpotlightView {
  id: string;
  label: string;
  image: ProductSpotlightImage;
}

export interface ProductSpotlightVariant {
  id: string;
  label: string;
  /** Any valid CSS color for the finish swatch. */
  color: string;
  image: ProductSpotlightImage;
  /** Extra images of this finish. The main image is always the first view. */
  views?: ProductSpotlightView[];
}

export interface ProductSpotlightSize {
  id: string;
  label: string;
  dimensions: string;
  /** A formatted price, including its currency. */
  price: string;
}

export interface ProductSpotlightSelection {
  variant: ProductSpotlightVariant | null;
  size: ProductSpotlightSize | null;
  view: ProductSpotlightView;
  image: ProductSpotlightImage;
}

export interface ProductSpotlightHeroProps {
  eyebrow?: string;
  title: string;
  description?: string;
  kicker?: string;
  note?: string;
  image: ProductSpotlightImage;
  features: ProductSpotlightFeature[];
  productName?: string;
  /** Decorative collection number behind the product. */
  productNumber?: string;
  variants?: ProductSpotlightVariant[];
  sizes?: ProductSpotlightSize[];
  /** Called only after a visitor changes finish, model, or view. */
  onSelectionChange?: (selection: ProductSpotlightSelection) => void;
  action?: { label: string; href: string };
  className?: string;
}

const emptyVariants: ProductSpotlightVariant[] = [];
const emptySizes: ProductSpotlightSize[] = [];

function position(value: number) {
  return `${Math.min(1, Math.max(0, Number.isFinite(value) ? value : .5)) * 100}%`;
}

function viewsFor(variant: ProductSpotlightVariant | null, image: ProductSpotlightImage) {
  return [{ id: 'main', label: 'Object', image: variant?.image ?? image }, ...(variant?.views ?? []).filter(view => view.id !== 'main')];
}

/** An image-led product introduction with a compact, usable configuration panel. */
export function ProductSpotlightHero({
  eyebrow,
  title,
  description,
  kicker,
  note,
  image,
  features,
  productName = 'OBJECT / 01',
  productNumber = '01',
  variants = emptyVariants,
  sizes = emptySizes,
  onSelectionChange,
  action,
  className = '',
}: ProductSpotlightHeroProps) {
  const [variantId, setVariantId] = useState<string | null>(null);
  const [sizeId, setSizeId] = useState<string | null>(null);
  const [viewId, setViewId] = useState('main');
  const [featureId, setFeatureId] = useState<string | null>(null);
  const [imageRatio, setImageRatio] = useState(1.5);
  const selectedVariant = variants.find(item => item.id === variantId) ?? variants[0] ?? null;
  const selectedSize = sizes.find(item => item.id === sizeId) ?? sizes[0] ?? null;
  const views = viewsFor(selectedVariant, image);
  const selectedView = views.find(item => item.id === viewId) ?? views[0];
  const selectedFeature = features.find(item => item.id === featureId);
  const instance = useId();
  const titleId = `ac-spotlight-title-${instance}`;
  const detailId = `ac-spotlight-detail-${instance}`;
  const summaryId = `ac-spotlight-summary-${instance}`;

  function chooseVariant(variant: ProductSpotlightVariant) {
    const view = viewsFor(variant, image)[0];
    setVariantId(variant.id);
    setViewId('main');
    setFeatureId(null);
    onSelectionChange?.({ variant, size: selectedSize, view, image: view.image });
  }

  function chooseSize(size: ProductSpotlightSize) {
    setSizeId(size.id);
    onSelectionChange?.({ variant: selectedVariant, size, view: selectedView, image: selectedView.image });
  }

  function chooseView(view: ProductSpotlightView) {
    setViewId(view.id);
    setFeatureId(null);
    onSelectionChange?.({ variant: selectedVariant, size: selectedSize, view, image: view.image });
  }

  return (
    <section className={`ac-product-spotlight-hero ${className}`.trim()} aria-labelledby={titleId}>
      <header className="ac-product-spotlight-masthead">
        <span className="ac-product-spotlight-wordmark">{productName}</span>
        <span className="ac-product-spotlight-edition">{eyebrow ?? 'AN OBJECT, CONSIDERED.'}</span>
        <span className="ac-product-spotlight-index" aria-hidden="true">({productNumber})</span>
      </header>

      <div className="ac-product-spotlight-stage">
        <div className="ac-product-spotlight-copy">
          {kicker && <span className="ac-product-spotlight-kicker"><span aria-hidden="true"/>{kicker}</span>}
          <h2 id={titleId}>{title}</h2>
          {description && <p className="ac-product-spotlight-description">{description}</p>}
          {note && <span className="ac-product-spotlight-scroll-note">{note}<span aria-hidden="true">↘</span></span>}
        </div>

        <div className="ac-product-spotlight-visual">
          <span className="ac-product-spotlight-watermark" aria-hidden="true">{productNumber}</span>
          <div className="ac-product-spotlight-image-area" data-view={selectedView.id} style={{ '--ac-spotlight-image-ratio': selectedView.id === 'main' ? imageRatio : 1.5 } as CSSProperties}>
            <img key={selectedView.image.src} src={selectedView.image.src} alt={selectedView.image.alt} onLoad={event => {
              const { naturalWidth, naturalHeight } = event.currentTarget;
              if (naturalWidth > 0 && naturalHeight > 0) setImageRatio(naturalWidth / naturalHeight);
            }} />
            {features.length > 0 && selectedView.id === 'main' && <div className="ac-product-spotlight-points" role="group" aria-label="Explore product details">
              {features.map((feature, index) => <button
                key={feature.id}
                type="button"
                className="ac-product-spotlight-point"
                style={{ left: position(feature.x), top: position(feature.y) }}
                aria-label={`Explore feature ${index + 1}: ${feature.label}`}
                aria-pressed={selectedFeature?.id === feature.id}
                aria-controls={detailId}
                onClick={() => setFeatureId(selectedFeature?.id === feature.id ? null : feature.id)}
              ><span aria-hidden="true">+</span></button>)}
            </div>}
          </div>
          <div className="ac-product-spotlight-visual-footer">
            <div className="ac-product-spotlight-view-controls" role="group" aria-label="Product views">
              {views.map((view, index) => <button key={view.id} type="button" data-view={view.id} aria-label={`View ${view.label}`} aria-pressed={selectedView.id === view.id} onClick={() => chooseView(view)}>
                <img src={view.image.src} alt="" loading="lazy"/><span className="ac-product-spotlight-view-name"><span aria-hidden="true">{String(index + 1).padStart(2, '0')}</span>{view.label}</span><span className="ac-product-spotlight-view-arrow" aria-hidden="true">↗</span>
              </button>)}
            </div>
            <span className="ac-product-spotlight-render-label">{selectedVariant?.label ?? 'PRODUCT STUDY'}<span aria-hidden="true"> / </span>{selectedView.label}</span>
          </div>
        </div>
      </div>

      {features.length > 0 && <div className="ac-product-spotlight-detail" id={detailId} aria-live="polite" aria-atomic="true">
        <span className="ac-product-spotlight-detail-label">IN THE DETAILS <span aria-hidden="true">↗</span></span>
        <div>{selectedFeature ? <><strong>{selectedFeature.label}</strong><span>{selectedFeature.detail}</span></> : <span>Explore the + points for a closer look at the design.</span>}</div>
      </div>}

      <div className="ac-product-spotlight-configuration" data-options={Number(variants.length > 0) + Number(sizes.length > 0)}>
        {variants.length > 0 && <fieldset className="ac-product-spotlight-finish">
          <legend>01 — Finish</legend>
          <div className="ac-product-spotlight-swatches">
            {variants.map(variant => <button key={variant.id} type="button" aria-label={`Finish: ${variant.label}`} aria-pressed={selectedVariant?.id === variant.id} onClick={() => chooseVariant(variant)} style={{ '--ac-spotlight-swatch': variant.color } as CSSProperties}>
              <span className="ac-product-spotlight-swatch-chip" aria-hidden="true"><span>✓</span></span><span className="ac-product-spotlight-swatch-name">{variant.label}</span>
            </button>)}
          </div>
        </fieldset>}
        {sizes.length > 0 && <fieldset className="ac-product-spotlight-model">
          <legend>02 — Model</legend>
          <div className="ac-product-spotlight-models">
            {sizes.map(size => <button key={size.id} type="button" aria-pressed={selectedSize?.id === size.id} aria-describedby={summaryId} onClick={() => chooseSize(size)}><span>{size.label}</span><span aria-hidden="true">{selectedSize?.id === size.id ? '●' : '○'}</span></button>)}
          </div>
        </fieldset>}
        <div className="ac-product-spotlight-purchase">
          <div className="ac-product-spotlight-summary" id={summaryId} aria-live="polite" aria-atomic="true">
            <div><strong>{selectedSize?.price ?? productName}</strong><span>{selectedSize?.dimensions ?? selectedVariant?.label ?? 'Explore the design'}</span></div>
            {selectedSize && <span className="ac-product-spotlight-summary-model">{selectedSize.label}{selectedVariant ? ` / ${selectedVariant.label}` : ''}</span>}
          </div>
          {action && <a className="ac-product-spotlight-action" href={action.href}>{action.label}<span aria-hidden="true">↗</span></a>}
        </div>
      </div>
    </section>
  );
}

.ac-product-spotlight-hero,
.ac-product-spotlight-hero * { box-sizing: border-box; }

.ac-product-spotlight-hero {
  --ac-spotlight-surface: #e7e6e2;
  --ac-spotlight-ink: #202220;
  --ac-spotlight-muted: #656762;
  --ac-spotlight-line: #c9cac5;
  --ac-spotlight-accent: #2851e3;
  width: 100%;
  max-width: 1920px;
  margin-inline: auto;
  container-type: inline-size;
  overflow: hidden;
  background: var(--ac-spotlight-surface);
  color: var(--ac-spotlight-ink);
  font-family: Arial, Helvetica, sans-serif;
  -webkit-font-smoothing: antialiased;
}

.ac-product-spotlight-masthead { display: flex; align-items: center; gap: 18px; min-height: 68px; margin: 0 32px; border-bottom: 1px solid var(--ac-spotlight-line); }
.ac-product-spotlight-wordmark { font-size: 27px; font-weight: 800; line-height: 1; letter-spacing: -.09em; }
.ac-product-spotlight-edition { margin-left: auto; color: var(--ac-spotlight-muted); font-size: 8px; letter-spacing: .08em; text-align: right; }
.ac-product-spotlight-index { margin-left: 36px; font-size: 10px; }
.ac-product-spotlight-stage { --ac-spotlight-stage-size: var(--ac-spotlight-stage-height, clamp(480px, 32cqi, 640px)); position: relative; display: grid; grid-template-columns: .85fr 1.15fr; align-items: center; height: var(--ac-spotlight-stage-size); min-height: 0; grid-template-rows: minmax(0, 1fr); padding: 35px 32px 24px; isolation: isolate; }
.ac-product-spotlight-copy { position: relative; z-index: 2; min-width: 0; padding-bottom: 0; }
.ac-product-spotlight-kicker { display: flex; align-items: center; gap: 6px; margin-bottom: 29px; color: var(--ac-spotlight-muted); font-size: 8px; line-height: 1.5; letter-spacing: .06em; }
.ac-product-spotlight-kicker > span { width: 4px; height: 4px; border-radius: 50%; background: var(--ac-spotlight-accent); }
.ac-product-spotlight-copy h2 { position: relative; max-width: 11ch; margin: 0; font-family: inherit; font-size: clamp(42px, 6.7cqi, 90px); line-height: .98; font-weight: 500; letter-spacing: -.075em; white-space: pre-line; text-wrap: balance; }
.ac-product-spotlight-description { max-width: 29ch; margin: 24px 0 0; color: var(--ac-spotlight-muted); font-size: 11px; line-height: 1.7; }
.ac-product-spotlight-scroll-note { display: flex; justify-content: space-between; align-items: center; max-width: 230px; margin-top: 40px; color: var(--ac-spotlight-muted); font-size: 7px; letter-spacing: .04em; }
.ac-product-spotlight-scroll-note > span { color: var(--ac-spotlight-ink); font-size: 25px; }
.ac-product-spotlight-visual { position: relative; z-index: 1; isolation: isolate; display: flex; flex-direction: column; justify-content: center; min-width: 0; min-height: 0; align-self: stretch; }
.ac-product-spotlight-watermark { position: absolute; z-index: -1; inset: 0 -2px 64px 0; display: flex; align-items: center; justify-content: flex-end; overflow: clip; color: #d2d3ce; font-size: min(47cqi, calc(var(--ac-spotlight-stage-size) - 124px)); line-height: .9; font-weight: 500; letter-spacing: -.115em; pointer-events: none; user-select: none; }
.ac-product-spotlight-image-area { position: relative; flex: 0 0 auto; align-self: center; width: min(120%, calc((var(--ac-spotlight-stage-size) - 124px) * var(--ac-spotlight-image-ratio, 1.5))); max-width: none; margin: 0; transform: translateX(-3%); }
.ac-product-spotlight-image-area > img { display: block; width: 100%; height: auto; animation: ac-spotlight-image-in 260ms ease both; }
.ac-product-spotlight-image-area[data-view]:not([data-view="main"]) { width: min(94%, calc((var(--ac-spotlight-stage-size) - 124px) * 1.5)); margin: 0 auto; overflow: hidden; border-radius: 2px; transform: none; }
.ac-product-spotlight-image-area[data-view]:not([data-view="main"]) > img { aspect-ratio: 1.5; object-fit: cover; }
.ac-product-spotlight-points { position: absolute; inset: 0; }
.ac-product-spotlight-point { display: grid; position: absolute; z-index: 1; place-items: center; width: 44px; height: 44px; padding: 0; transform: translate(-50%, -50%); border: 0; border-radius: 50%; background: transparent; color: #fff; font: inherit; cursor: pointer; }
.ac-product-spotlight-point > span { display: grid; place-items: center; width: 23px; height: 23px; border: 1px solid rgb(255 255 255 / 75%); border-radius: 50%; background: rgb(29 32 30 / 52%); box-shadow: 0 0 0 5px rgb(255 255 255 / 10%); font-size: 17px; line-height: 1; transition: background 160ms ease, transform 160ms ease; }
.ac-product-spotlight-point[aria-pressed="true"] > span { background: var(--ac-spotlight-accent); transform: rotate(45deg); }
.ac-product-spotlight-visual-footer { position: relative; display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-top: auto; padding: 16px 0 0; }
.ac-product-spotlight-view-controls { display: flex; flex-wrap: wrap; gap: 4px; }
.ac-product-spotlight-view-controls > button { display: inline-flex; align-items: center; justify-content: space-between; gap: 7px; min-height: 48px; padding: 5px 9px 5px 5px; border: 1px solid var(--ac-spotlight-line); background: transparent; color: var(--ac-spotlight-muted); font: inherit; font-size: 9px; cursor: pointer; transition: background 160ms ease, color 160ms ease; }
.ac-product-spotlight-view-controls > button > img { display: block; width: 43px; height: 32px; border-radius: 1px; background: rgb(255 255 255 / 35%); object-fit: contain; }
.ac-product-spotlight-view-controls > button[data-view]:not([data-view="main"]) > img { object-fit: cover; }
.ac-product-spotlight-view-name { display: flex; flex-direction: column; align-items: start; gap: 4px; }
.ac-product-spotlight-view-name > span { font-size: 6px; opacity: .65; }
.ac-product-spotlight-view-controls > button[aria-pressed="true"] { border-color: var(--ac-spotlight-ink); background: var(--ac-spotlight-ink); color: var(--ac-spotlight-surface); }
.ac-product-spotlight-view-arrow { margin-left: 12px; font-size: 14px; }
.ac-product-spotlight-render-label { font-size: 7px; line-height: 1.5; text-align: right; color: var(--ac-spotlight-muted); text-transform: uppercase; letter-spacing: .06em; }
.ac-product-spotlight-detail { display: grid; grid-template-columns: 180px minmax(0, 1fr); gap: 22px; align-items: center; min-height: 52px; padding: 9px 32px; border-top: 1px solid var(--ac-spotlight-line); font-size: 10px; }
.ac-product-spotlight-detail-label { display: flex; justify-content: space-between; gap: 20px; color: var(--ac-spotlight-muted); font-size: 7px; letter-spacing: .06em; }
.ac-product-spotlight-detail-label > span { color: var(--ac-spotlight-ink); font-size: 15px; }
.ac-product-spotlight-detail > div { display: flex; flex-wrap: wrap; align-items: baseline; column-gap: 12px; row-gap: 3px; color: var(--ac-spotlight-muted); line-height: 1.5; }
.ac-product-spotlight-detail strong { color: var(--ac-spotlight-ink); font-size: 10px; font-weight: 500; }
.ac-product-spotlight-configuration { display: grid; grid-template-columns: minmax(0, .9fr) minmax(0, 1.05fr) minmax(0, 1.2fr); border-top: 1px solid var(--ac-spotlight-line); background: rgb(255 255 255 / 18%); }
.ac-product-spotlight-configuration > fieldset { min-width: 0; margin: 0; padding: 20px 24px 24px; border: 0; border-right: 1px solid var(--ac-spotlight-line); }
.ac-product-spotlight-configuration > fieldset > legend { float: left; width: 100%; margin: 0 0 19px; padding: 0; color: var(--ac-spotlight-muted); font-size: 8px; letter-spacing: .035em; }
.ac-product-spotlight-swatches { display: flex; clear: both; align-items: start; gap: 18px; }
.ac-product-spotlight-swatches > button { display: flex; flex-direction: column; align-items: center; justify-content: start; gap: 7px; min-width: 44px; min-height: 65px; padding: 0; border: 0; background: transparent; color: var(--ac-spotlight-muted); font: inherit; font-size: 8px; cursor: pointer; }
.ac-product-spotlight-swatch-chip { display: grid; place-items: center; width: 31px; height: 31px; margin: 4px; border: 1px solid rgb(0 0 0 / 13%); border-radius: 50%; background: var(--ac-spotlight-swatch); outline: 1px solid transparent; outline-offset: 4px; transition: outline-color 160ms ease; }
.ac-product-spotlight-swatch-chip > span { display: grid; place-items: center; width: 14px; height: 14px; border-radius: 50%; opacity: 0; background: #fff; color: #202220; font-size: 9px; }
.ac-product-spotlight-swatches > button[aria-pressed="true"] .ac-product-spotlight-swatch-chip { outline-color: var(--ac-spotlight-ink); }
.ac-product-spotlight-swatches > button[aria-pressed="true"] .ac-product-spotlight-swatch-chip > span { opacity: 1; }
.ac-product-spotlight-swatches > button[aria-pressed="true"] { color: var(--ac-spotlight-ink); }
.ac-product-spotlight-models { display: flex; flex-wrap: wrap; clear: both; gap: 6px; }
.ac-product-spotlight-models > button { display: flex; align-items: center; justify-content: space-between; flex: 1 1 85px; gap: 13px; min-height: 44px; padding: 10px; border: 1px solid var(--ac-spotlight-line); background: transparent; color: var(--ac-spotlight-muted); font: inherit; font-size: 9px; text-align: left; cursor: pointer; transition: border-color 160ms ease, color 160ms ease; }
.ac-product-spotlight-models > button > span:last-child { font-size: 9px; }
.ac-product-spotlight-models > button[aria-pressed="true"] { border-color: var(--ac-spotlight-ink); color: var(--ac-spotlight-ink); }
.ac-product-spotlight-purchase { min-width: 0; padding: 20px 24px 24px; }
.ac-product-spotlight-summary { display: flex; justify-content: space-between; align-items: start; gap: 12px; min-height: 61px; }
.ac-product-spotlight-summary > div { display: flex; flex-direction: column; gap: 6px; }
.ac-product-spotlight-summary strong { font-size: 30px; line-height: 1; font-weight: 500; letter-spacing: -.065em; }
.ac-product-spotlight-summary > div > span { color: var(--ac-spotlight-muted); font-size: 8px; line-height: 1.5; }
.ac-product-spotlight-summary-model { max-width: 70px; color: var(--ac-spotlight-muted); font-size: 7px; line-height: 1.5; text-align: right; }
.ac-product-spotlight-action { display: flex; align-items: center; justify-content: space-between; width: 100%; min-height: 44px; gap: 20px; margin-top: 12px; padding: 12px 15px; border: 1px solid var(--ac-spotlight-accent); background: var(--ac-spotlight-accent); color: #fff; font-size: 10px; line-height: 1.4; font-weight: 400; text-decoration: none; transition: background 160ms ease, border-color 160ms ease; }
.ac-product-spotlight-action > span { font-size: 17px; line-height: 1; }
.ac-product-spotlight-configuration[data-options="1"] { grid-template-columns: 1fr 1fr; }
.ac-product-spotlight-configuration[data-options="0"] { grid-template-columns: 1fr; }
.ac-product-spotlight-configuration[data-options="0"] .ac-product-spotlight-purchase { display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.ac-product-spotlight-configuration[data-options="0"] .ac-product-spotlight-action { max-width: 240px; margin-top: 0; }
.ac-product-spotlight-hero :is(button, a):focus-visible { outline: 2px solid var(--ac-spotlight-accent); outline-offset: 4px; }

@keyframes ac-spotlight-image-in { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
@media (hover: hover) and (pointer: fine) {
  .ac-product-spotlight-point:hover > span { background: var(--ac-spotlight-accent); }
  .ac-product-spotlight-view-controls > button:hover { border-color: var(--ac-spotlight-ink); }
  .ac-product-spotlight-swatches > button:hover .ac-product-spotlight-swatch-chip { outline-color: var(--ac-spotlight-muted); }
  .ac-product-spotlight-models > button:hover { border-color: var(--ac-spotlight-ink); color: var(--ac-spotlight-ink); }
  .ac-product-spotlight-action:hover { border-color: var(--ac-spotlight-ink); background: var(--ac-spotlight-ink); }
}

@container (min-width: 1150px) {
  .ac-product-spotlight-masthead { margin-inline: 48px; min-height: 80px; }
  .ac-product-spotlight-stage { padding-inline: 48px; }
  .ac-product-spotlight-detail { padding-inline: 48px; }
  .ac-product-spotlight-configuration > fieldset,
  .ac-product-spotlight-purchase { padding-inline: 34px; }
}
@container (width < 1150px) {
  .ac-product-spotlight-stage { --ac-spotlight-stage-size: var(--ac-spotlight-stage-height, clamp(320px, calc(100svh - 375px), 560px)); }
}
@container (max-width: 760px) {
  .ac-product-spotlight-masthead { margin-inline: 24px; min-height: 58px; }
  .ac-product-spotlight-wordmark { font-size: 23px; }
  .ac-product-spotlight-edition { font-size: 6px; }
  .ac-product-spotlight-index { margin-left: 10px; font-size: 8px; }
  .ac-product-spotlight-stage { grid-template-columns: 1fr 1.1fr; padding: 28px 24px 18px; }
  .ac-product-spotlight-kicker { margin-bottom: 24px; font-size: 6px; }
  .ac-product-spotlight-copy { padding-bottom: 0; }
  .ac-product-spotlight-copy h2 { font-size: clamp(36px, 6.6cqi, 52px); }
  .ac-product-spotlight-description { max-width: 26ch; margin-top: 18px; font-size: 9px; }
  .ac-product-spotlight-scroll-note { margin-top: 30px; font-size: 5px; }
  .ac-product-spotlight-watermark { top: 20px; }
  .ac-product-spotlight-render-label { display: none; }
  .ac-product-spotlight-visual-footer { padding-top: 10px; }
  .ac-product-spotlight-view-controls > button { min-height: 44px; padding: 5px 8px 5px 5px; font-size: 8px; }
  .ac-product-spotlight-view-arrow { margin-left: 2px; }
  .ac-product-spotlight-detail { grid-template-columns: 110px minmax(0, 1fr); gap: 20px; padding-inline: 24px; }
  .ac-product-spotlight-detail > div { font-size: 8px; }
  .ac-product-spotlight-detail strong { font-size: 8px; }
  .ac-product-spotlight-detail-label { font-size: 6px; }
  .ac-product-spotlight-configuration { grid-template-columns: 1fr 1fr; }
  .ac-product-spotlight-configuration > fieldset { padding: 18px 24px; }
  .ac-product-spotlight-configuration > fieldset > legend { margin-bottom: 14px; }
  .ac-product-spotlight-model { border-right: 0 !important; }
  .ac-product-spotlight-purchase { grid-column: 1 / -1; display: flex; align-items: center; gap: 24px; padding: 20px 24px; border-top: 1px solid var(--ac-spotlight-line); }
